"""Parameter defaults, tuning constraints and learned-asset schemas.

Inputs are literal configuration or tensor shapes; outputs are copied metadata.
No numerical work runs here. Build emits native PARAMS/PARAM_SPACE literals from
this inventory; edit each default here once. Runtime validation retains tensors.
"""
from __future__ import annotations
import math


def _parameter(default, owner, doc, *, shape='scalar', kind='continuous',
               trainable=True, bounds=(-20.0, 20.0), allowed=None, choices=None):
    spec = dict(default=default, shape=shape, kind=kind, trainable=trainable,
                owner=owner, doc=doc, per_layer_option=shape == 'scalar' and kind == 'continuous')
    if allowed is None:
        spec['bounds'] = bounds
    else:
        spec['allowed'] = allowed
    if choices is not None:
        spec['choices'] = choices
    return spec


