def copy_parameter_structure(value):
    if isinstance(value, dict):
        return {key: copy_parameter_structure(v) for key, v in value.items()}
    if isinstance(value, list):
        return [copy_parameter_structure(v) for v in value]
    if isinstance(value, tuple):
        return tuple(copy_parameter_structure(v) for v in value)
    return value


def parameter_defaults():
    return {name: copy_parameter_structure(spec['default']) for name, spec in PARAMETER_REGISTRY.items()}


def parameter_space():
    return {name: {'choice': copy_parameter_structure(spec.get('choices', [spec['default']]))}
            for name, spec in PARAMETER_REGISTRY.items()}


def _asset(shape, *, dtype='float32', trainable=True, owner='corrector', trainer='tools/train'):
    return dict(shape=shape, dtype=dtype, kind='continuous', bounds=None,
                trainable=trainable, owner=owner, trainer=trainer)


