def parameter_shape(value):
    if hasattr(value, 'shape'):
        return tuple(value.shape)
    if isinstance(value, dict):
        return {key: parameter_shape(v) for (key, v) in value.items()}
    if isinstance(value, (list, tuple)):
        shapes = [parameter_shape(v) for v in value]
        if shapes and (not all((s == shapes[0] for s in shapes))):
            raise ValueError('Ragged parameter table')
        return (len(value),) + (shapes[0] if shapes else ())
    return ()

def normalize_parameter(name, value):
    """Restore table keys/tuple containers after a JSON round trip; retain tensors."""
    def restore(template, incoming):
        if isinstance(template, dict) and isinstance(incoming, dict):
            keys = {str(key): key for key in template}
            return {keys.get(str(key), key): restore(template[keys[str(key)]], item)
                    if str(key) in keys else item for key, item in incoming.items()}
        if isinstance(template, (list, tuple)) and isinstance(incoming, (list, tuple)):
            items = [restore(template[index], item) if index < len(template) else item
                     for index, item in enumerate(incoming)]
            return tuple(items) if isinstance(template, tuple) else items
        return incoming
    return restore(PARAMETER_REGISTRY[name]['default'], value)


def optional_asset_registry(feature_names, feature_registry):
    width = sum(feature_registry[name]['width'] for name in feature_names)
    def entry(name, shape, doc):
        return dict(name=name, shape=shape, dtype='float32', owner='corrector',
                    trainer='tools/train', trainable=True, kind='continuous',
                    default='zeros', bounds=None, doc=doc)
    result = {
        'linear.weight': entry('linear.weight', (16, width, 19), "T=X@weight[layer][features['columns']]+bias[layer] (corrector.linear_corrections).\nper-layer[16,feature_width,19]; trainable; 0 feature connection off; 1 unit weight (identity requires a matching matrix)."),
        'linear.bias': entry('linear.bias', (16, 19), "T=X@weight[layer][features['columns']]+bias[layer] (corrector.linear_corrections).\nper-layer[16,19]; trainable; 0 no linear readout offset; 1 unit offset."),
    }
    original = ('marginals', 'pairs', 'physics', 'bias', 'carry', 'birth_inputs')
    for name in feature_names:
        if name not in original:
            key = 'feature_weights.' + name
            result[key] = entry(key, (16, feature_registry[name]['width'], 64),
                                'Win includes feature_weights[name][layer][columns]; e=concat(parts)@Win (corrector.configured_input_weights).\nper-layer[16,feature_width[name],64]; trainable; 0 extra-feature connection off; 1 unit weight (identity requires a matching matrix).')
    return result


def validate_parameter(name, value):
    entry = PARAMETER_REGISTRY[name]
    if parameter_shape(value) != parameter_shape(entry['default']):
        raise ValueError('Parameter shape mismatch: ' + name)
    if hasattr(value, 'shape'):
        if entry['kind'] == 'discrete':
            raise ValueError('Discrete parameters require Python literals: ' + name)
        return
    if isinstance(value, dict):
        if set(value) != set(entry['default']):
            raise ValueError('Parameter table keys mismatch: ' + name)
        values = value.values()
    elif isinstance(value, (list, tuple)):
        values = value
    else:
        values = (value,)

    def check(v):
        if isinstance(v, (tuple, list)):
            for x in v:
                check(x)
        elif isinstance(v, dict):
            for x in v.values():
                check(x)
        elif hasattr(v, 'shape'):
            return
        elif isinstance(v, (int, float)):
            if not math.isfinite(v):
                raise ValueError('Nonfinite parameter: ' + name)
            if 'bounds' in entry and (not entry['bounds'][0] <= v <= entry['bounds'][1]):
                raise ValueError('Parameter out of bounds: ' + name)
        elif not (isinstance(v, str) and isinstance(entry['default'], str)):
            raise ValueError('Unsupported parameter type: ' + name)
    for v in values:
        check(v)
    if 'allowed' in entry and value not in entry['allowed']:
        raise ValueError('Parameter outside allowed set: ' + name)
    if entry['kind'] == 'discrete' and isinstance(entry['default'], int) and (not isinstance(value, int)):
        raise ValueError('Integer parameter required: ' + name)

def expand_scalar_parameter(name, values=None):
    """Registry opt-in: a length-16 literal/tensor schedule with scalar defaults."""
    entry = PARAMETER_REGISTRY[name]
    if not entry['per_layer_option']:
        raise ValueError('Not a scalar continuous parameter: ' + name)
    result = tuple([entry['default']] * 16) if values is None else values
    if parameter_shape(result) != (16,):
        raise ValueError('Expected 16 layer values: ' + name)
    for value in result:
        validate_parameter(name, value)
    return result

def validate_k4_schedules(params, schedules):
    """Historical banks cannot recover a vertex omitted at its birth layer."""
    for name in ('k4_star_scale', 'k4_d22c_scale', 'k4_d31c_scale', 'k4_d40o_scale'):
        if name not in schedules:
            continue
        values = schedules[name]
        if name == 'k4_star_scale':
            if bool(params[name] == 0) or any(bool(value == 0) for value in values):
                raise ValueError('Scheduled k4 source bank must stay enabled')
        else:
            disabled = False
            for value in values:
                if bool(value == 0):
                    disabled = True
                elif disabled:
                    raise ValueError('Cannot reactivate a disabled historical k4 vertex: ' + name)

def validate_asset_tensor(name, value):
    spec = ASSET_REGISTRY[name]
    if tuple(value.shape) != tuple(spec['shape']):
        raise ValueError('Asset tensor shape mismatch: ' + name)
    dtype = str(value.dtype).removeprefix('torch.')
    if dtype != spec['dtype']:
        raise ValueError('Asset tensor dtype mismatch: ' + name)
